package android.app;import android.content.Context;import android.graphics.Bitmap;import java.util.*;
public class Notification {
 public static final String CATEGORY_RECOMMENDATION="recommendation";
 public String title,text,subText,category;public PendingIntent tap;public Bitmap icon;public Object style;public final List<Action> actions=new ArrayList<>();
 public static class Action {public String label;public PendingIntent tap;public static class Builder {Action a=new Action();public Builder(int icon,String label,PendingIntent tap){a.label=label;a.tap=tap;}public Action build(){return a;}}}
 public static class Builder {Notification n=new Notification();public Builder(Context c,String channel){}public Builder setSmallIcon(int v){return this;}public Builder setColor(int v){return this;}public Builder setContentIntent(PendingIntent v){n.tap=v;return this;}public Builder setAutoCancel(boolean v){return this;}public Builder setWhen(long v){return this;}public Builder setShowWhen(boolean v){return this;}public Builder setContentTitle(String s){n.title=s;return this;}public Builder setContentText(String s){n.text=s;return this;}public Builder setSubText(String s){n.subText=s;return this;}public Builder setCategory(String s){n.category=s;return this;}public Builder setLargeIcon(Bitmap b){n.icon=b;return this;}public Builder addAction(Action a){n.actions.add(a);return this;}public Builder setStyle(Object s){n.style=s;return this;}public Notification build(){return n;}}
 public static class BigTextStyle {public String title,text,summary;public BigTextStyle setBigContentTitle(String s){title=s;return this;}public BigTextStyle bigText(String s){text=s;return this;}public BigTextStyle setSummaryText(String s){summary=s;return this;}}
 public static class InboxStyle {public String title,summary;public List<String> lines=new ArrayList<>();public InboxStyle setBigContentTitle(String s){title=s;return this;}public InboxStyle addLine(String s){lines.add(s);return this;}public InboxStyle setSummaryText(String s){summary=s;return this;}}
}
